ommons/thumb/3/3a/MUTEK_Museum_voor_Toegepaste_Europese_Kunst_in_voormalige_tweede_klas_wachtkamer%2C_Station_Haarlem.jpg/1280px-MUTEK_Museum_voor_Toegepaste_Europese_Kunst_in_voormalige_tweede_klas_wachtkamer%2C_Station_Haarlem.jpg","caption":"MUTEK - Museum voor Toegepaste Europese Kunst — MUTEK Museum voor Toegepaste Europese Kunst in voormalige tweede klas wachtkamer, Station Haarlem","credit":"Moldenme","source_url":"https://commons.wikimedia.org/wiki/File:MUTEK_Museum_voor_Toegepaste_Europese_Kunst_in_voormalige_tweede_klas_wachtkamer,_Station_Haarlem.jpg","license":"CC BY-SA 4.0"}],"is_art_museum":true},{"id":"298d8b42-77ec-5527-a6b8-580dfddb071d","inventory_key":"museum-nl:kunstlinie-almere-kunsthal","name":"Kunstlinie","city":"Almere","province":"Flevoland","street_address":"Esplanade 10","postal_code":"1315 TA","country":"NL","website_url":"https://kunstlinie.nl","latitude":52.367105,"longitude":5.218819,"summary":"Ontdek hedendaagse kunst die aansluit bij de wereld om je heen. Kunstlinie brengt nationale en internationale makers naar Almere. Wisselende tentoonstellingen geven ruimte aan nieuwe perspectieven, herkenning en gesprek.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["kunsthal","hedendaagse kunst"],"photos":[{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/84/Kunstlinie_Almere_20220210_123350.jpg/1280px-Kunstlinie_Almere_20220210_123350.jpg","caption":"Kunstlinie — Kunstlinie Almere 20220210 123350","credit":"GeeJee","source_url":"https://commons.wikimedia.org/wiki/File:Kunstlinie_Almere_20220210_123350.jpg","license":"CC BY-SA 4.0"}],"is_art_museum":true},{"id":"a429aa0c-7446-5b60-b7fe-6561e704365d","inventory_key":"wikipedia:Zeeland:panoramawalcheren:vlissingen","name":"Museum Panorama Walcheren","city":"Vlissingen","province":"Zeeland","street_address":"Singel 106","postal_code":"","country":"NL","website_url":"https://panoramawalcheren.nl/nl/","latitude":null,"longitude":null,"