be0-362c41604103","inventory_key":"art-audit:217","name":"Pier Pander Museum","city":"Leeuwarden","province":"Friesland","street_address":"Groeneweg 1","postal_code":"8911 EH","country":"NL","website_url":"https://historischcentrumleeuwarden.nl/pier-pander","latitude":null,"longitude":null,"summary":"Ontmoet de verstilde beeldhouwkunst van Pier Pander. Het museum vertelt over zijn leven en werk; de bijbehorende tempel geeft zijn marmeren figuren een bijzondere omgeving. Een kleine bestemming voor aandachtig kijken.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["beeldhouwkunst","kunstenaarsmuseum"],"photos":[{"url":"https://upload.wikimedia.org/wikipedia/commons/6/64/Pier_Pander_museum_Leeuwarden_Prinsentuin.JPG","caption":"Pier Pander Museum — Pier Pander museum Leeuwarden Prinsentuin","credit":"Vidi Condor","source_url":"https://commons.wikimedia.org/wiki/File:Pier_Pander_museum_Leeuwarden_Prinsentuin.JPG","license":"CC BY 4.0"}],"is_art_museum":true},{"id":"2335783a-59fe-5be9-b370-5e3629208b6d","inventory_key":"wikipedia:Noord-Holland:kattenkabinet:amsterdam","name":"KattenKabinet","city":"Amsterdam","province":"Noord-Holland","street_address":"Herengracht 497","postal_code":"1017 BT","country":"NL","website_url":"https://www.kattenkabinet.nl/","latitude":null,"longitude":null,"summary":"Ontdek hoe katten kunstenaars blijven inspireren. Schilderijen, prenten en sculpturen tonen het dier als huisgenoot, symbool en eigenzinnig personage. Het KattenKabinet verenigt uiteenlopende stijlen rond één onweerstaanbaar onderwerp.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["schilderkunst","prentkunst","beeldhouwkunst","dieren"],"photos":[{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/a/ad/Amsterdam_-_Herengracht_497.JPG/1280px-Amsterdam_-_Herengracht_497.JPG","caption":"KattenKabinet — Amsterdam - Herengracht 497","credit":"Rudolphous","source_url":"https://commons.wikimedia.org/wiki/File:Amsterdam_-_Herengracht_497.JPG","license":"CC BY-SA 3.0"}],"is_art_museum":true},{"id":"ffded4b9-b725-50f6-8e41-ddaebec64e1b","inventory_key":"wikipedia:Gelderland:museumveluwezoom:doorwerth","name":"Museum Veluwezoom","city":"Doorwerth","province":"Gelderland","street_address":"Fonteinallee 2b","postal_code":"6865 ND","country":"NL","website_url":"https://www.museumveluwezoom.nl/","latitude":null,"longitude":null,"summary":"Ontdek de schilders die aan de Veluwezoom hun inspiratie vonden. Werk uit Oosterbeek en omgeving toont de aantrekkingskracht van bos, rivier en landleven. De verzameling volgt kunstenaars door verschillende generaties heen.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["schilderkunst","landschap","kunstenaarskolonie"],"photos":[{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/80/Kasteel_Doorwerth._%28actm%29_01.jpg/1280px-Kasteel_Doorwerth._%28actm%29_01.jpg","caption":"Museum Veluwezoom — Kasteel Doorwerth. (actm) 01","credit":"Agnes Monkelbaan","source_url":"https://commons.wikimedia.org/wiki/File:Kasteel_Doorwerth._(actm)_01.jpg","license":"CC BY-SA 4.0"}],"is_art_museum":true},{"id":"3378c57b-4660-5174-81f0-beccdc0c3723","inventory_key":"wikipedia:Zuid-Holland:atlasvanstolk:rotterdam","name":"Atlas van Stolk","city":"Rotterdam","province":"Zuid-Holland","street_address":"Librijesteeg 4","postal_code":"3011 HN","country":"NL","website_url":"https://www.atlasvanstolk.nl/","latitude":null,"longitude":null,"summary":"Ontdek hoe beelden geschiedenis vertellen. Atlas Van Stolk verzamelt prenten, foto''s en ander beeldmateriaal rond Nederland. Satire, nieuws en alledaagse scènes laten zien hoe makers gebeurtenissen in beeld hebben gebracht.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["prentkunst","fotografie","beeldcultuur"],"photos":[],"is_art_museum":true},{"id":"f09ec0cb-1e19-5a97-9e65-4e3ee620ec73","inventory_key":"wikipedia:Utrecht:hofjevanmevrouwvanaerden:leerdam","name":"Hofje van Aerden","city":"Leerdam","province":"Zuid-Holland","street_address":"Kerkstraat 67","postal_code":"4141 AV","country":"NL","website_url":"https://hofjevanaerden.nl/","latitude":null,"longitude":null,"summary":"Ontdek Hollandse schilderkunst in een intieme historische omgeving. Het Hofje van Mevrouw van Aerden bewaart een verzameling met werken van zeventiende-eeuwse meesters. De bescheiden schaal nodigt uit om details rustig op je in te laten werken.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["oude meesters","schilderkunst"],"photos":[{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/3/3d/WLM_-_mchangsp_-_Hofje_van_Mevrouw_van_Aerden.jpg/1280px-WLM_-_mchangsp_-_Hofje_van_Mevrouw_van_Aerden.jpg","caption":"Hofje van Aerden — WLM - mchangsp - Hofje van Mevrouw van Aerden","credit":"Marc Chang Sing Pang","source_url":"https://commons.wikimedia.org/wiki/File:WLM_-_mchangsp_-_Hofje_van_Mevrouw_van_Aerden.jpg","license":"CC BY-SA 2.0"}],"is_art_museum":true},{"id":"ac8b9843-593c-5589-a793-c54029d518c8","inventory_key":"museum-nl:kunstfort-vijfhuizen","name":"Kunstfort bij Vijfhuizen","city":"Vijfhuizen","province":"Noord-Holland","street_address":"Fortwachter 1","postal_code":"2141 EE","country":"NL","website_url":"https://www.kunstfort.nl/","latitude":52.347407,"longitude":4.670797,"summary":"Ontdek hedendaagse kunst in en rond een voormalig fort. Kunstenaars reageren op de bijzondere ruimte, het landschap en actuele vragen. Binnen- en buitenwerken geven het militaire erfgoed een nieuwe betekenis.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["hedendaagse kunst","beeldhouwkunst","kunsthal"],"photos":[{"url":"https://upload.wikimedia.org/wikipedia/commons/d/dd/Vijfhuizen_fort.jpg","caption":"Kunstfort bij Vijfhuizen — Vijfhuizen fort","credit":"Arch","source_url":"https://commons.wikimedia.org/wiki/File:Vijfhuizen_fort.jpg","license":"Public domain"}],"is_art_museum":true},{"id":"dbc1b2a9-b3fe-5eba-ac29-9fbc44c0ad82","inventory_key":"museum-nl:abc-architectuurcentrum-haarlem","name":"ABC Architectuurcentrum Haarlem","city":"Haarlem","province":"Noord-Holland","street_address":"Groot Heiligland 47","postal_code":"2011 EP","country":"NL","website_url":"https://www.architectuurhaarlem.nl/","latitude":52.37711,"longitude":4.634042,"summary":"Kijk met nieuwe ogen naar gebouwen en steden. ABC Architectuurcentrum presenteert tentoonstellingen over de ontworpen omgeving. Maquettes, beelden en ideeën helpen je begrijpen hoe architectuur het dagelijks leven vormt.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["architectuur","design"],"photos":[{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/3/34/Haarlem_Historisch_Museum_-_Groot_Heiligland_47.jpg/1280px-Haarlem_Historisch_Museum_-_Groot_Heiligland_47.jpg","caption":"ABC Architectuurcentrum Haarlem — Haarlem Historisch Museum - Groot Heiligland 47","credit":"Jane023 ( talk ) 13:56, 29 November 2010 (UTC)","source_url":"https://commons.wikimedia.org/wiki/File:Haarlem_Historisch_Museum_-_Groot_Heiligland_47.jpg","license":"CC BY 3.0"}],"is_art_museum":true},{"id":"b1dec3a0-2a14-5d8b-be26-19068c22967f","inventory_key":"art-audit:227","name":"Noorderlicht. Studio | Festival | On Tour","city":"Groningen","province":"Groningen","street_address":"Akerkhof 12","postal_code":"9711 JB","country":"NL","website_url":"https://www.noorderlicht.com","latitude":null,"longitude":null,"summary":"Ontdek fotografie die vragen stelt over de wereld. Noorderlicht presenteert tentoonstellingen, projecten en festivals rond eigentijdse beelden. Verschillende makers laten zien hoe een foto tegelijk kan informeren, ontregelen en ontroeren.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["fotografie","beeldcultuur","kunsthal"],"photos":[{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/9/92/Groningen_-_Akerkhof_12_%281%29.jpg/1280px-Groningen_-_Akerkhof_12_%281%29.jpg","caption":"Noorderlicht. Studio | Festival | On Tour — Groningen - Akerkhof 12 (1)","credit":"Hardscarf","source_url":"https://commons.wikimedia.org/wiki/File:Groningen_-_Akerkhof_12_(1).jpg","license":"CC BY-SA 3.0 nl"}],"is_art_museum":true}]'::jsonb)
 on conflict(id) do update set inventory_key=excluded.inventory_key,name=excluded.name,city=excluded.city,province=excluded.province,street_address=excluded.street_address,postal_code=excluded.postal_code,country=excluded.country,website_url=excluded.website_url,latitude=excluded.latitude,longitude=excluded.longitude,summary=excluded.summary,operating_status=excluded.operating_status,publication_status=excluded.publication_status,verification_status=excluded.verification_status,tags=excluded.tags,photos=excluded.photos,is_art_museum=excluded.is_art_museum
 where not m.is_art_museum and m.publication_status='draft'
 and not exists(select 1 from kunstkiezer_private.museum_changes c where c.museum_id=m.id and c.editor_id is not null)
 returning id
) insert into kk_art_changed select id from changed;
